def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_d = 0
    opp_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    coop_rate = float(n - opp_d) / float(n)

    after_my_d_c = 0
    after_my_d_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                after_my_d_c += 1
            else:
                after_my_d_d += 1

    window = min(6, n)
    recent_opp_d = 0
    recent_my_d = 0
    for i in range(n - window, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
        if history[i][0] == 'D':
            recent_my_d += 1

    last_a, last_b = history[-1]

    cons_d = 0
    for a, b in reversed(history):
        if b == 'D':
            cons_d += 1
        else:
            break

    cons_c = 0
    for a, b in reversed(history):
        if b == 'C':
            cons_c += 1
        else:
            break

    if opp_d == 0:
        if my_d == 0:
            if n >= 8 and last_a == 'C' and last_b == 'C':
                return 'D'
            return 'C'
        if after_my_d_c > 0:
            return 'D'
        if last_a == 'D':
            return 'C'
        return 'C'

    if (last_b == 'C' and my_d > 0 and after_my_d_c > 0 and
            after_my_d_d == 0 and recent_opp_d == 0 and
            coop_rate >= 0.80 and cons_c >= 2 and n < 95):
        return 'D'

    if last_b == 'D':
        if coop_rate >= 0.65:
            if last_a == 'D':
                return 'C'
            if recent_my_d > 0:
                if cons_d == 1:
                    return 'C'
                if cons_d == 2 and rng.random() < 0.6:
                    return 'C'
                return 'D'
            if cons_d == 1:
                return 'D'
            if rng.random() < 0.2:
                return 'C'
            return 'D'

        if coop_rate >= 0.35:
            if last_a == 'D':
                return 'C'
            if recent_my_d > 0 and cons_d == 1:
                return 'C'
            if rng.random() < 0.1:
                return 'C'
            return 'D'

        if cons_d >= 5 and rng.random() < 0.06:
            return 'C'
        return 'D'

    if coop_rate < 0.25:
        return 'D'
    if recent_opp_d >= 3 and coop_rate < 0.55:
        return 'D'
    if coop_rate >= 0.45:
        return 'C'
    if cons_c >= 2 and rng.random() < 0.2:
        return 'C'
    return 'D'
